<?php
namespace App\Services;
use App\Enums\{LicenseStatus,InstallationStatus,SecurityEventType}; use App\Models\{License,Installation,InstallationEvent,SecurityEvent}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
final class ActivationService { public function __construct(private HardwareFingerprint $fingerprints,private LicenseKeyService $keys,private LicenseStateService $states){} public function activate(string $key,array $data,string $ip,?string $requestId):array { return DB::transaction(function()use($key,$data,$ip,$requestId){ $license=License::where('license_key_hash',$this->keys->hash($key))->lockForUpdate()->first(); if(!$license)return ['error'=>['LICENSE_NOT_FOUND','License was not found.',404]]; if($error=$this->states->validateLicense($license))return ['error'=>$error]; $fp=$this->fingerprints->make($data['hardware'],$data['fingerprint_version']??1); $existing=$license->installations()->where('fingerprint',$fp)->first(); if($existing)return ['installation'=>$existing,'token'=>null]; if($license->installations()->where('status','!=',InstallationStatus::Inactive->value)->count()>=$license->max_installations)return ['error'=>['LICENSE_INSTALLATION_LIMIT','Installation limit reached.',409]]; $token='oit_'.Str::random(64); $installation=Installation::create(array_merge(['license_id'=>$license->id,'customer_id'=>$license->customer_id,'product_id'=>$license->product_id,'release_id'=>$license->release_id,'installation_token_hash'=>hash('sha256',$token),'hostname'=>$data['hostname'],'fingerprint'=>$fp,'fingerprint_version'=>$data['fingerprint_version']??1,'cpu_model'=>$data['hardware']['cpu_model']??null,'cpu_cores'=>$data['hardware']['cpu_cores']??null,'ram_bytes'=>$data['hardware']['ram_bytes']??null,'disk_size_bytes'=>$data['hardware']['disk_size_bytes']??null,'os_name'=>$data['os']['name']??null,'os_version'=>$data['os']['version']??null,'kernel_version'=>$data['os']['kernel']??null,'virtualization_type'=>$data['hardware']['virtualization_type']??null,'agent_version'=>$data['agent_version']??null,'application_version'=>$data['application_version']??null,'first_ip'=>$ip,'last_ip'=>$ip,'first_seen_at'=>now(),'last_seen_at'=>now(),'activated_at'=>now(),'status'=>InstallationStatus::Active],$this->fingerprints->componentHashes($data['hardware']))); $license->update(['status'=>LicenseStatus::Active,'activated_at'=>$license->activated_at??now()]); InstallationEvent::create(['installation_id'=>$installation->id,'type'=>'activated','context'=>['request_id'=>$requestId],'occurred_at'=>now()]); return ['installation'=>$installation,'token'=>$token]; },5); } public function verifyFingerprint(Installation $installation,array $hardware,string $ip,?string $requestId):?array { $incoming=$this->fingerprints->make($hardware,$installation->fingerprint_version); if(hash_equals($installation->fingerprint,$incoming))return null; SecurityEvent::create(['type'=>SecurityEventType::CloneDetected,'license_id'=>$installation->license_id,'installation_id'=>$installation->id,'ip_address'=>$ip,'request_id'=>$requestId,'context'=>['presented_fingerprint'=>hash('sha256',$incoming)],'occurred_at'=>now()]); InstallationEvent::create(['installation_id'=>$installation->id,'type'=>'clone_detected','context'=>['request_id'=>$requestId],'occurred_at'=>now()]); return ['LICENSE_HARDWARE_MISMATCH','Hardware does not match the signed installation binding.',403]; } }
